const npvOf=(flows:number[],rate:number)=>flows.reduce((sum,v,i)=>sum+v/Math.pow(1+rate,i),0)
const irrOf=(flows:number[]):number|null=>{if(!flows.some(x=>x>0)||!flows.some(x=>x<0))return null;let lo=-.95,hi=5;let flo=npvOf(flows,lo),fhi=npvOf(flows,hi);if(flo*fhi>0)return null;for(let i=0;i<120;i++){const mid=(lo+hi)/2,fmid=npvOf(flows,mid);if(Math.abs(fmid)<1e-7)return mid;if(flo*fmid>0){lo=mid;flo=fmid}else{hi=mid;fhi=fmid}}return (lo+hi)/2}
const paybackOf=(flows:number[],rate=0)=>{let acc=0;for(let i=0;i<flows.length;i++){const v=flows[i]/Math.pow(1+rate,i);if(acc+v>=0&&v>0)return i+(0-acc)/v;acc+=v}return null}

